    jest.spyOn(Math, 'random').mockRestore();
  });

  it('clamps to maxMs', () => {
    jest.spyOn(Math, 'random').mockReturnValue(0.5);
    const delay = retryDelay(10, 1000, 5000);
    expect(delay).toBe(5000);
